CREATE POLICY "anexos: membros podem ver" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'anexos' AND public.is_member(((storage.foldername(name))[1])::uuid));
CREATE POLICY "anexos: membros podem enviar" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'anexos' AND public.is_member(((storage.foldername(name))[1])::uuid));
CREATE POLICY "anexos: membros podem atualizar" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'anexos' AND public.is_member(((storage.foldername(name))[1])::uuid)) WITH CHECK (bucket_id = 'anexos' AND public.is_member(((storage.foldername(name))[1])::uuid));
CREATE POLICY "anexos: membros podem apagar" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'anexos' AND public.is_member(((storage.foldername(name))[1])::uuid));